const express = require("express");
const checks = require("./checks");
const ui = require("./ui");
const db = require("./db");

const app = express();
app.use(express.urlencoded({ extended: false }));
app.use(express.json());

// ---- SQLite: the table is created once; all students are saved in database.db ----
db.run("CREATE TABLE IF NOT EXISTS students (id INTEGER PRIMARY KEY, name TEXT, marks INTEGER)");
const students = db.rows("SELECT name, marks FROM students ORDER BY id").map((r) => ({ name: r.name, marks: Number(r.marks) }));

function save() {
  // simple way: clear the table, insert everyone again
  db.many([["DELETE FROM students", []], ...students.map((s) => ["INSERT INTO students (name, marks) VALUES (?, ?)", [s.name, s.marks]])]);
}

app.get("/", (req, res) => {
  const S = checks.loadAll();
  const form = '<form method="post" action="/add">' + ui.part(S[2]) + ui.part(S[3]) + ui.part(S[4]) + "</form>";

  let list;
  if (students.length === 0) {
    list = '<p style="color:#6b7480">No students yet. Add one above.</p>';
  } else if (S[5].status !== "done") {
    list = ui.box(S[5]) + `<p style="color:#6b7480">(${students.length} student(s) saved, but not shown yet)</p>`;
  } else {
    const rows = students.map((s, i) => {
      const row = String(ui.part(S[5], { name: ui.esc(s.name), marks: s.marks }));
      let extra = "";
      if (S[7].status === "done") extra += `<span class="badge">Grade ${S[7].f(s.marks)}</span>`;
      if (S[9].status === "done") extra += `<a class="del" href="/delete/${i}" title="Delete">❌</a>`;
      return row.includes("</li>") ? row.replace("</li>", extra + "</li>") : row + extra;
    });
    list = "<ul>" + rows.join("") + "</ul>";
    if (S[7].status !== "done") list += ui.box(S[7]);
    if (S[9].status !== "done") list += ui.box(S[9]);
  }

  let stats;
  if (S[6].status === "done" && students.length) {
    const total = S[6].f(students);
    stats = `<div class="stats"><div class="stat">Total<b>${total}</b></div><div class="stat">Average<b>${(total / students.length).toFixed(1)}</b></div></div>`;
  } else if (S[6].status === "done") {
    stats = '<p style="color:#6b7480">Total and average appear after you add students.</p>';
  } else stats = ui.box(S[6]);

  let top = "";
  if (S[8].status === "done" && students.length) {
    const t = S[8].f(students);
    top = `<h2>🏆 Topper: ${ui.esc(t.name)} (${t.marks})</h2>`;
  } else if (S[8].status !== "done") top = ui.box(S[8]);

  const inner =
    '<div class="card">' + ui.part(S[1]) + form + "</div>" +
    '<div class="card"><h2>Students</h2>' + list + "</div>" +
    '<div class="card">' + stats + top + "</div>" +
    ui.part(S[10]) +
    '<p style="text-align:center"><a href="/reset" style="color:#6b7480">Clear all students</a> · API: <a href="/api/students">/api/students</a></p>';
  res.send(ui.page("Marks Analyzer", S, inner));
});

app.post("/add", (req, res) => {
  const name = String(req.body.name || "").trim() || "Student " + (students.length + 1);
  const marks = parseInt(req.body.marks, 10) || 0;
  students.push({ name, marks });
  save();
  res.redirect("/");
});

app.get("/delete/:i", (req, res) => {
  const s = checks.load(9);
  const i = Number(req.params.i);
  if (s.status === "done" && i >= 0 && i < students.length) { s.f(students, i); save(); }
  res.redirect("/");
});

app.get("/reset", (req, res) => { students.length = 0; save(); res.redirect("/"); });

// ==============================================================
//  API (CRUD): ready-made. Call it with curl: commands/08_api_crud.txt
//  Create = POST · Read = GET · Update = PUT · Delete = DELETE
// ==============================================================
app.get("/api/students", (req, res) => {          // READ    SELECT * FROM students
  res.json(students.map((s, i) => ({ id: i, name: s.name, marks: s.marks })));
});

app.post("/api/students", (req, res) => {         // CREATE  INSERT INTO students ...
  const name = String((req.body || {}).name || "").trim();
  const marks = Number((req.body || {}).marks);
  if (!name) return res.status(400).json({ error: "name is required" });
  if (!Number.isFinite(marks)) return res.status(400).json({ error: "marks must be a number" });
  students.push({ name, marks });
  save();
  res.status(201).json({ id: students.length - 1, name, marks });
});

app.put("/api/students/:i", (req, res) => {       // UPDATE  UPDATE students SET marks = ...
  const i = Number(req.params.i);
  if (!(i >= 0 && i < students.length)) return res.status(404).json({ error: "student not found" });
  const marks = Number((req.body || {}).marks);
  if (!Number.isFinite(marks)) return res.status(400).json({ error: "marks must be a number" });
  students[i].marks = marks;
  save();
  res.json({ id: i, ...students[i] });
});

app.delete("/api/students/:i", (req, res) => {    // DELETE  DELETE FROM students WHERE id = ...
  const i = Number(req.params.i);
  if (!(i >= 0 && i < students.length)) return res.status(404).json({ error: "student not found" });
  const gone = students.splice(i, 1)[0];
  save();
  res.json({ deleted: gone.name });
});

app.listen(3000, () => console.log("\n  👉 Open http://localhost:3000 in your browser.  (Stop: Ctrl + C)\n"));
